      { t: 'p', p: '<b>法術階級</b>：自己施放看該法術本身的階級；<b>武器免費觸發</b>的法術則改看<b>武器有多稀有</b>——傳說／遺物武器固定 <b>5 階（×1.5）</b>，一般武器越罕見階級越高。' }
