  // 屬性附加魔法可抽到的技能表:直接讀遊戲的 ATTR_MAGIC_SKILLS(js/08)+DB.skills 名稱,作者調整池子/觸發率會自動反映。
  // 觸發率欄位是「一星」的值;實際觸發率 = 基礎 × 星數(getAttrMagicProc)。
  // 祝福率:對照 js/08 gainItem 的 blessRate 預設(頭目 0.10／其他 0.01)、js/14 製作端傳 0.10、
  //   js/07 rollAffixesNew 的席琳分支(一般怪 ×3/×5、頭目改「固定 20%／30%」而非倍率)。
  function blessRateTableHtml() {
    return wTbl(['來源', '帶「祝福的」機率'], [
      ['打怪（一般怪）', '<b>1%</b>'],
      ['打怪（頭目）', '<b>10%</b>'],
      ['製作／合成', '<b>10%</b>'],
      ['潘朵拉黑市的裝備商品', '<b>1%</b>'],
      ['席琳的世界・一般怪', '<b>3%</b>'],
      ['瘋狂的席琳世界・一般怪', '<b>5%</b>'],
      ['席琳的世界・頭目', '<b>20%</b>（固定值，不是 10% 再乘倍率）'],
      ['瘋狂的席琳世界・頭目', '<b>30%</b>（固定值）']
    ]);
  }
  function attrMagicTableHtml() {
    if (typeof ATTR_MAGIC_SKILLS === 'undefined' || !ATTR_MAGIC_SKILLS) return '';
    var ELE_ZH = { fire: '火', water: '水', wind: '風', earth: '地' };
    var rows = [];
    ['fire', 'water', 'wind', 'earth'].forEach(function (e) {
      var pool = ATTR_MAGIC_SKILLS[e];
      if (!pool || !pool.length) return;
      var txt = pool.slice().sort(function (a, b) { return b.rate - a.rate; }).map(function (p) {
        var nm = (typeof DB !== 'undefined' && DB.skills && DB.skills[p.skId] && DB.skills[p.skId].n) || '';
        return nm ? (esc(nm) + '（' + p.rate + '%）') : '';
      }).filter(Boolean).join('、');
      if (txt) rows.push(['<b>' + ELE_ZH[e] + '</b>', txt]);
    });
    return rows.length ? wTbl(['屬性', '可能抽到的魔法（括號＝一星觸發率）'], rows) : '';
  }

