    m_resonance: ['基準：光箭吃魔抗、回 MP＝傷害/10 → 精通：傷害 +5、無視魔抗、回 MP＝傷害/5'],
    m_strike: ['原生魔擊＝必中＋必重擊的物理攻擊，觸發率＝力量/60', '持共鳴杖：光箭（智力/60）改發魔擊（力量/60）、不再回 MP；持魔爆武器：魔爆（全體 智力/60／單體 智力/100）改發魔擊＋擴散——觸發從吃智力改吃力量'],
    m_echo: ['觸發率＝(11−法術階級)×10%：一階 100%、三階 80%、五階 60%', '單體傷害魔法再 ×2（如五階單體＝120%＝必定連發）；連發那次免 MP、不再連鎖'],
