    e_magic: ['MP −50% 只作用在「與自身選定屬性相同」的傷害魔法；四個高階法術照法師的等級需求學'],
    d_poison: ['基準：50% 觸發、每秒 60% 攻擊傷害 → 精通：100%、每秒 200%（持續 5 秒共 5 跳、固定 1 層）', '上毒門檻：新毒單跳要比現有毒高才會覆蓋刷新，否則等舊毒跑完'],
