      '<b>每個角色每天 1 次</b>：通關成功時，<b>主戰角色與當時出戰的每位傭兵都會扣掉今天的次數</b>——帶傭兵打等於一次用掉好幾個角色的額度。',
      '每天 <b>UTC+8 凌晨 12 點</b>重置；挑戰失敗或中途離開<b>不消耗</b>次數。',
