      '<b>挑戰失敗或中途離開「不消耗」次數</b>：只有真正打通（擊敗最終頭目）才會記下今天已通關。所以沒把握也能先進去試。',
      '行動受限（石化／麻痺／冰凍／暈眩／沉睡）時不能進；<b>正受僱為別人的傭兵</b>時也不能進（受僱期間只能待安全區）。'
