      '區內<b>不能從地圖選單切別的圖</b>，也<b>不能用傳送術與瞬間移動卷軸</b>（地圖列只顯示目前區域名）。',
      '<b>按「回村」＝中途離開</b>（視同放棄、不耗每日次數）；<b>在副本內死亡＝挑戰失敗</b>（回村、同樣不耗次數）。狀態<b>不存檔</b>：重新整理／關掉再開都會回村作廢。'
