        + '<tr><td style="padding:4px 6px;">① 入口</td><td style="padding:4px 6px;">喀瑪焰王（Lv62、HP 約 1.5 萬）</td></tr>'
        + '<tr><td style="padding:4px 6px;">② 通道</td><td style="padding:4px 6px;">喀瑪南王（Lv62、HP 約 1.3 萬）</td></tr>'
        + '<tr><td style="padding:4px 6px;">③ 深處</td><td style="padding:4px 6px;">喀瑪王（Lv70、HP 約 2.5 萬）</td></tr>'
        + '<tr><td style="padding:4px 6px;">④ 棲息地</td><td style="padding:4px 6px;">被侵蝕的安塔瑞斯（三段變身，見下）</td></tr>'
