      '<b>被侵蝕的安塔瑞斯</b>（Lv85、HP 9 萬）→ <b>被侵蝕的狂怒安塔瑞斯</b>（Lv90、HP 18 萬）→ <b>被侵蝕的瘋狂安塔瑞斯</b>（Lv95、HP 36 萬）。',
      '<b>只有最終階「瘋狂安塔瑞斯」會死亡並結算掉落</b>——打倒最終階＝通關，自動送回威頓村、記下相同模式今天已通關。',
      '最終階會放劇毒噴吐（中毒）、巨岩炮／地裂術、集體衝暈、毀滅隕石等<b>全體技</b>，愈後面階段愈兇；免疫中毒（安塔瑞斯系列盔甲）與抗地屬性會很有用。'
